import sys
from io import StringIO

def read_input():
    input = sys.stdin.read
    data = input().split()
    return int(data[0]), list(data[1])

def solve(N, sequence):
    left_word = []
    right_word = list(sequence)

    while len(right_word) > 0:
        left_word.append(right_word.pop())

    if ''.join(left_word) < ''.join(right_word):
        return "DA", ''.join(left_word)
    else:
        return "NE", ''.join(left_word)

