def can_slavko_win_and_get_beautiful_word(N, sequence):
    # Since Mirko goes first and always takes the leftmost letter,
    # Slavko will take the rightmost letter each time.
    # This means Slavko's word will be the reverse of Mirko's word.

    # Determine if Slavko can potentially win by comparing the sequences
    mirko_word = ''
    slavko_word = ''

    for i in range(N):
        if i % 2 == 0:
            mirko_word += sequence[i]
        else:
            slavko_word += sequence[N-1-i]

    # Check if Slavko's word is lexicographically smaller
    if slavko_word < mirko_word:
        return "DA", slavko_word
    else:
        return "NE", ""

