def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    sequence = data[1]

    # Calculate the prefix sums of character frequencies modulo 26
    prefix_sum = [0] * (26)
    for char in sequence:
        prefix_sum[ord(char) - ord('a')] += 1

    # Check if Slavko can force a win
    has_odd = False
    for count in prefix_sum:
        if count % 2 != 0:
            has_odd = True
            break

    if has_odd:
